onClick:
{{(() => {
     const address = (NewDropoffAddressInput.text || "").trim();
     if (address.length < 4) {
       showAlert("Въведете адрес преди да търсите", "warning");
       return;
     }
     // The postcode is required and travels with every search (Ico, 2026-10-04): without it
     // Google places some streets in the wrong part of town. The query appends it.
     const zip = (NewDropoffPostcodeInput.text || "").trim();
     if (!/^\d{4}$/.test(zip)) {
       showAlert("Въведете пощенския код на получателя (4 цифри) преди да търсите", "warning");
       return;
     }
     // Google drops "бул." and may answer a village the merchant never typed (Кътина for
     // бул. Сливница 566, 2026-10-03). The query spells the abbreviation out; if the answer
     // still names a town that is not in the text, ask once more in Latin, and if that
     // misses too the pin is refused - the server refuses the same order the same way.
     const found = () => GeocodeNewDropoffAddress.data?.results?.length > 0;
     const settle = (retried) => {
       if (!found()) {
         showAlert("Адресът не е намерен — проверете изписването", "warning");
         return;
       }
       const town = LocationManager.wrongTown(GeocodeNewDropoffAddress.data.results[0], address);
       if (town && !retried) {
         return GeocodeNewDropoffAddress.run({ address: LocationManager.latinQuery(address) + ", " + zip + " Sofia" }).then(() => settle(true));
       }
       if (town) {
         NewDropoffLatHidden.setValue("");
         NewDropoffLngHidden.setValue("");
         showAlert(`Google намира адреса в ${town}, а не в София. Проверете улицата и номера, или изпишете квартала/селото.`, "warning");
         return;
       }
       LocationManager.updateNewDropoffFromGeocode();
     };
     GeocodeNewDropoffAddress.run()
       .then(() => settle(false))
       .catch(() => showAlert("Търсенето на адреса не мина. Опитайте пак.", "error"));
   })()}}
